#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n;
    cin >> n;
    const int OFFSET = 50000;
    const int NEG = -1e9;
    vector<int> dp(OFFSET * 2 + 1, NEG), nextDp;
    dp[OFFSET] = 0;
    for (int i = 0; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        nextDp = dp;
        int diff = a - b;
        int gain = a + b;
        for (int j = 0; j < (int)dp.size(); ++j) {
            if (dp[j] == NEG) continue;
            int nj = j + diff;
            if (0 <= nj && nj < (int)dp.size()) {
                nextDp[nj] = max(nextDp[nj], dp[j] + gain);
            }
        }
        dp.swap(nextDp);
    }
    cout << max(0, dp[OFFSET]) << "\n";
    return 0;
}

