#include <iostream>
using namespace std;
long long parentNode(long long x) {
    if (x <= 1) return 0;
    for (long long p = 2; p * p <= x; ++p) {
        if (x % p == 0) return x / p;
    }
    return 1;
}
int depthNode(long long x) {
    int depth = 0;
    while (x > 1) {
        x = parentNode(x);
        ++depth;
    }
    return depth;
}
int main() {
    int q;
    cin >> q;
    while (q--) {
        long long x, y;
        cin >> x >> y;
        int dx = depthNode(x);
        int dy = depthNode(y);
        int answer = 0;
        while (dx > dy) {
            x = parentNode(x);
            --dx;
            ++answer;
        }
        while (dy > dx) {
            y = parentNode(y);
            --dy;
            ++answer;
        }
        while (x != y) {
            x = parentNode(x);
            y = parentNode(y);
            answer += 2;
        }
        cout << answer << "\n";
    }
    return 0;
}

#include <algorithm>
#include <iostream>
using namespace std;
bool can(long long total, long long n, long long m, long long a, long long b) {
    if (a == b) return total * a <= min(n, m);
    long long diff = a - b;
    if (diff < 0) {
        swap(n, m);
        swap(a, b);
        diff = -diff;
    }
    long long left = max(0LL, (a * total - m + diff - 1) / diff);
    long long right = min(total, (n - b * total) / diff);
    return left <= right;
}
int main() {
    long long n, m, a, b;
    cin >> n >> m >> a >> b;
    long long left = 0, right = (n + m) / (a + b), answer = 0;
    while (left <= right) {
        long long mid = (left + right) / 2;
        if (can(mid, n, m, a, b)) {
            answer = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    cout << answer << "\n";
    return 0;
}

