#include <functional>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>
using namespace std;
int main() {
    int n, m, s, q;
    cin >> n >> m >> s >> q;
    vector<vector<pair<int, int>>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    const long long INF = (1LL << 62);
    vector<long long> dist(n + 1, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : graph[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    while (q--) {
        int h;
        cin >> h;
        cout << dist[h] << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n, a;
    cin >> n >> a;
    vector<vector<int>> graph(n + 1);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    const int LOG = 18;
    vector<int> depth(n + 1, 0), parent(n + 1, 0), order;
    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
    order.reserve(n);
    order.push_back(1);
    parent[1] = 0;
    for (int i = 0; i < (int)order.size(); ++i) {
        int u = order[i];
        for (int v : graph[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            depth[v] = depth[u] + 1;
            order.push_back(v);
        }
    }
    for (int i = 1; i <= n; ++i) up[0][i] = parent[i];
    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= n; ++i) {
            up[j][i] = up[j - 1][i] ? up[j - 1][up[j - 1][i]] : 0;
        }
    }
    auto lca = [&](int u, int v) {
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; ++j) {
            if (diff & (1 << j)) u = up[j][u];
        }
        if (u == v) return u;
        for (int j = LOG - 1; j >= 0; --j) {
            if (up[j][u] != up[j][v]) {
                u = up[j][u];
                v = up[j][v];
            }
        }
        return parent[u];
    };
    vector<long long> diff(n + 1, 0);
    for (int i = 0; i < a; ++i) {
        int u, v;
        cin >> u >> v;
        int w = lca(u, v);
        diff[u] += 1;
        diff[v] += 1;
        diff[w] -= 1;
        if (parent[w]) diff[parent[w]] -= 1;
    }
    int bu, bv;
    cin >> bu >> bv;
    vector<long long> cover = diff;
    for (int i = n - 1; i >= 1; --i) {
        int u = order[i];
        cover[parent[u]] += cover[u];
    }
    int w = lca(bu, bv);
    int answer = 0;
    int u = bu;
    while (u != w) {
        if (cover[u] == 0) ++answer;
        u = parent[u];
    }
    vector<int> path;
    u = bv;
    while (u != w) {
        path.push_back(u);
        u = parent[u];
    }
    if (cover[w] == 0) ++answer;
    for (int i = (int)path.size() - 1; i >= 0; --i) {
        if (cover[path[i]] == 0) ++answer;
    }
    cout << answer << "\n";
    return 0;
}

