long long gcdll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int main() {
    long long m, n;
    cin >> m >> n;
    cout << m / gcdll(m, n) * n << "\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;
long long modPow(long long a, long long e, long long mod) {
    long long result = 1 % mod;
    while (e > 0) {
        if (e & 1) result = result * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return result;
}
int main() {
    int T;
    cin >> T;
    while (T--) {
        long long a, p;
        cin >> a >> p;
        long long phi = p - 1;
        vector<long long> factors;
        long long x = phi;
        for (long long d = 2; d * d <= x; ++d) {
            if (x % d != 0) continue;
            factors.push_back(d);
            while (x % d == 0) x /= d;
        }
        if (x > 1) factors.push_back(x);
        bool ok = true;
        for (long long q : factors) {
            if (modPow(a, phi / q, p) == 1) {
                ok = false;
                break;
            }
        }
        cout << (ok ? "Yes" : "No") << "\n";
    }
    return 0;
}

