using namespace std;
const int MAXN = 505;
int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<bitset<MAXN>> incoming(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        incoming[v].set(u);
        incoming[u].set(v);
    }
    vector<bitset<MAXN>> current(n + 1), nextState(n + 1);
    vector<vector<int>> answer(n + 1, vector<int>(k + 1, 0));
    for (int i = 1; i <= n; ++i) current[i].set(i);
    for (int step = 1; step <= k; ++step) {
        for (int s = 1; s <= n; ++s) {
            nextState[s].reset();
            for (int v = 1; v <= n; ++v) {
                if ((current[s] & incoming[v]).any()) {
                    nextState[s].set(v);
                }
            }
            answer[s][step] = static_cast<int>(nextState[s].count());
        }
        current.swap(nextState);
    }
    for (int s = 1; s <= n; ++s) {
        for (int step = 1; step <= k; ++step) {
            if (step > 1) cout << ' ';
            cout << answer[s][step];
        }
        cout << "\n";
    }
    return 0;
}

