#include <iostream>
#include <vector>
using namespace std;
const long long MOD = 1000000007LL;
int main() {
    int n, m;
    cin >> n >> m;
    vector<int> out(n + 1, 0), in(n + 1, 0), parent(n + 1);
    vector<int> degree(n + 1, 0);
    for (int i = 1; i <= n; ++i) parent[i] = i;
    auto find = [&](int x) {
        int r = x;
        while (parent[r] != r) r = parent[r];
        while (parent[x] != x) {
            int p = parent[x];
            parent[x] = r;
            x = p;
        }
        return r;
    };
    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a != b) parent[a] = b;
    };
    bool ok = true;
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        if (out[a] || in[b]) ok = false;
        out[a] = b;
        in[b] = a;
        ++degree[a];
        ++degree[b];
        if (degree[a] > 2 || degree[b] > 2) ok = false;
        unite(a, b);
    }
    if (ok) {
        vector<int> nodeCount(n + 1, 0), headCount(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            int r = find(i);
            ++nodeCount[r];
            if (in[i] == 0) ++headCount[r];
        }
        for (int i = 1; i <= n; ++i) {
            if (nodeCount[i] > 1 && headCount[i] != 1) ok = false;
        }
    }
    if (!ok) {
        cout << 0 << "\n";
        return 0;
    }
    int components = 0;
    vector<int> seen(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int r = find(i);
        if (!seen[r]) {
            seen[r] = 1;
            ++components;
        }
    }
    long long answer = 1;
    for (int i = 2; i <= components; ++i) answer = answer * i % MOD;
    cout << answer << "\n";
    return 0;
}

