            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                order.push_back(v);
            }
        }
        vector<int> need(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            int u = order[i];
            need[u] = treasure[u];
