#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
struct Student {
    int c, m, e, idx;
};
bool sameRank(const Student& a, const Student& b) {
    return a.c + a.m + a.e == b.c + b.m + b.e &&
           a.c + a.m == b.c + b.m &&
           max(a.c, a.m) == max(b.c, b.m);
}
int main() {
    int n;
    cin >> n;
    vector<Student> students(n);
    for (int i = 0; i < n; ++i) {
        cin >> students[i].c >> students[i].m >> students[i].e;
        students[i].idx = i;
    }
    vector<Student> order = students;
    sort(order.begin(), order.end(), [](const Student& a, const Student& b) {
        int sa = a.c + a.m + a.e;
        int sb = b.c + b.m + b.e;
        if (sa != sb) return sa > sb;
        int ca = a.c + a.m;
        int cb = b.c + b.m;
        if (ca != cb) return ca > cb;
        int ma = max(a.c, a.m);
        int mb = max(b.c, b.m);
        if (ma != mb) return ma > mb;
        return a.idx < b.idx;
    });
    vector<int> rank(n);
    int currentRank = 1;
    for (int i = 0; i < n; ++i) {
        if (i > 0 && !sameRank(order[i], order[i - 1])) currentRank = i + 1;
        rank[order[i].idx] = currentRank;
    }
    for (int i = 0; i < n; ++i) cout << rank[i] << "\n";
    return 0;
}

