#include <algorithm>
#include <iostream>
#include <queue>
#include <set>
#include <utility>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> color(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) cin >> color[i][j];
    }

    vector<vector<int>> visited(n, vector<int>(m, 0));
    set<vector<pair<int, int>>> shapes;
    const int dr[4] = {1, -1, 0, 0};
    const int dc[4] = {0, 0, 1, -1};

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (visited[r][c]) continue;
            int currentColor = color[r][c];
            queue<pair<int, int>> q;
            vector<pair<int, int>> cells;
            visited[r][c] = 1;
            q.push({r, c});
            while (!q.empty()) {
                auto [x, y] = q.front();
                q.pop();
                cells.push_back({x, y});
                for (int dir = 0; dir < 4; ++dir) {
                    int nx = x + dr[dir];
                    int ny = y + dc[dir];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                    if (visited[nx][ny] || color[nx][ny] != currentColor) continue;
                    visited[nx][ny] = 1;
                    q.push({nx, ny});
                }
            }

            int minRow = n, minCol = m;
            for (auto [x, y] : cells) {
                minRow = min(minRow, x);
                minCol = min(minCol, y);
            }
            vector<pair<int, int>> normalized;
            normalized.reserve(cells.size());
            for (auto [x, y] : cells) normalized.push_back({x - minRow, y - minCol});
            sort(normalized.begin(), normalized.end());
            shapes.insert(normalized);
        }
    }

    cout << shapes.size() << "\n";
    return 0;
}

