int main() {
    int n;
    cin >> n;
    vector<int> parent(n, 0), depth(n, 0);
    for (int i = 1; i < n; ++i) cin >> parent[i];
    for (int i = 1; i < n; ++i) depth[i] = depth[parent[i]] + 1;

    int lg = 1;
    while ((1 << lg) <= n) ++lg;
    vector<vector<int>> up(lg, vector<int>(n, 0));
    vector<vector<int>> best(lg, vector<int>(n, 0));
    for (int v = 0; v < n; ++v) {
        up[0][v] = parent[v];
        best[0][v] = max(v, parent[v]);
    }
    best[0][0] = 0;
    for (int j = 1; j < lg; ++j) {
        for (int v = 0; v < n; ++v) {
            up[j][v] = up[j - 1][up[j - 1][v]];
            best[j][v] = max(best[j - 1][v], best[j - 1][up[j - 1][v]]);
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) swap(a, b);
        int diff = depth[a] - depth[b];
        for (int j = 0; j < lg; ++j) {
            if ((diff >> j) & 1) a = up[j][a];
        }
        if (a == b) return a;
        for (int j = lg - 1; j >= 0; --j) {
            if (up[j][a] != up[j][b]) {
                a = up[j][a];
                b = up[j][b];
            }
        }
        return parent[a];
    };

    auto maxOnPathToRoot = [&](int v) {
        int answer = v;
        int diff = depth[v];
        for (int j = lg - 1; j >= 0; --j) {
            if ((diff >> j) & 1) {
                answer = max(answer, best[j][v]);
                v = up[j][v];
            }
        }
        return answer;
    };

    int q;
    cin >> q;
    while (q--) {
        int m;
        cin >> m;
        int root;
        cin >> root;
        for (int i = 1; i < m; ++i) {
            int x;
            cin >> x;
            root = lca(root, x);
        }
        cout << maxOnPathToRoot(root) << "\n";
    }
    return 0;
}

