    }
    long long answer = 0;
    while (!chosen.empty()) {
        answer += chosen.top();
        chosen.pop();
    }
    cout << answer << "\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

struct Fenwick {
    int n;
    vector<int> tree;
    explicit Fenwick(int n) : n(n), tree(n + 1, 0) {}
    void add(int index, int delta) {
        ++index;
        while (index <= n) {
            tree[index] += delta;
            index += index & -index;
        }
    }
    int sumPrefix(int index) const {
        ++index;
        int result = 0;
        while (index > 0) {
            result += tree[index];
            index -= index & -index;
        }
        return result;
    }
};

int main() {
    int n;
    cin >> n;
    Fenwick bit(n);
    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        answer += bit.sumPrefix(x - 1);
        bit.add(x, 1);
    }
    cout << answer << "\n";
    return 0;
}

