int compressDigit(int x) {
    x *= 7;
    while (x > 9) {
        int sum = 0;
        while (x > 0) {
            sum += x % 10;
            x /= 10;
        }
        x = sum;
    }
    return x;
}

bool isLucky(long long x) {
    int position = 1;
    int total = 0;
    while (x > 0) {
        int digit = static_cast<int>(x % 10);
        if (position % 2 == 1) total += compressDigit(digit);
        else total += digit;
        x /= 10;
        ++position;
    }
    return total % 8 == 0;
}

